func TestMetadataPublicClock(t *testing.T) {
	m := &IqB1foHWg{Rf6N7kY6GVCs: 6, WyK3yKmJKe1V: uint32(time.Now().Unix() / 60), HPUJVQ0S: 65535}
	wire := m.Marshal()
	got, err := Ox0UfI5kIfcR(wire[:])
	if err != nil || !reflect.DeepEqual(got, m) {
		t.Fatalf("got %#v %v", got, err)
	}
}
